// PokePat mod platinum-exp-share: the Exp. Share is switched on and off.
static const charcode_t sExpShareOnText[] = {
    CHAR_E, CHAR_x, CHAR_p, CHAR_PERIOD, CHAR_SPACE,
    CHAR_S, CHAR_h, CHAR_a, CHAR_r, CHAR_e, CHAR_SPACE,
    CHAR_o, CHAR_n, CHAR_PERIOD, CHAR_EOS
};

static const charcode_t sExpShareOffText[] = {
    CHAR_E, CHAR_x, CHAR_p, CHAR_PERIOD, CHAR_SPACE,
    CHAR_S, CHAR_h, CHAR_a, CHAR_r, CHAR_e, CHAR_SPACE,
    CHAR_o, CHAR_f, CHAR_f, CHAR_PERIOD, CHAR_EOS
};

static UnkStruct_02068EFC *CreateExpShareMessageData(const charcode_t *message)
{
    UnkStruct_02068EFC *v0 = Heap_Alloc(HEAP_ID_FIELD2, sizeof(UnkStruct_02068EFC));

    v0->unk_16 = 0;
    v0->unk_10 = String_Init(128, HEAP_ID_FIELD2);
    String_CopyChars(v0->unk_10, message);

    return v0;
}

static const charcode_t *ToggleExpShare(FieldSystem *fieldSystem)
{
    VarsFlags *varsFlags = SaveData_GetVarsFlags(fieldSystem->saveData);

    if (VarsFlags_CheckFlag(varsFlags, FLAG_EXP_SHARE_ENABLED) == TRUE) {
        VarsFlags_ClearFlag(varsFlags, FLAG_EXP_SHARE_ENABLED);
        return sExpShareOffText;
    }

    VarsFlags_SetFlag(varsFlags, FLAG_EXP_SHARE_ENABLED);
    return sExpShareOnText;
}

static void UseExpShareFromMenu(ItemMenuUseContext *usageContext, const ItemUseContext *additionalContext)
{
    FieldSystem *fieldSystem = FieldTask_GetFieldSystem(usageContext->fieldTask);
    StartMenu *menu = FieldTask_GetEnv(usageContext->fieldTask);
    const charcode_t *message = ToggleExpShare(fieldSystem);

    FieldSystem_StartFieldMap(fieldSystem);
    menu->callback = PrintRegisteredKeyItemUseMessage;
    menu->taskData = CreateExpShareMessageData(message);
    menu->state = START_MENU_STATE_NEW_TASK;
}

static BOOL UseExpShareInField(ItemFieldUseContext *usageContext)
{
    const charcode_t *message = ToggleExpShare(usageContext->fieldSystem);

    FieldSystem_CreateTask(usageContext->fieldSystem, PrintRegisteredKeyItemUseMessage, CreateExpShareMessageData(message));
    return FALSE;
}

